// Package model holds every data type shared across packages in one place:
// the database row types (aliases of the sqlc-generated ones, so the schema stays
// the source of truth) and the plain structs passed to the store.
package model

import (
	"time"

	"sevi/internal/store/db"
)

// Database rows, as generated by sqlc from sql/migrations.
type (
	Session     = db.Session
	Message     = db.Message
	Pending     = db.Pending
	LedgerRow   = db.Ledger
	Page        = db.PageCache
	CachedAudio = db.AudioCache
	SessionCost = db.SessionCostRow
)

// LedgerEntry is a provider call that just succeeded. Units are tokens.
// CostUSD is nil when the model's price could not be determined.
type LedgerEntry struct {
	SessionID    string
	Role         string // llm | stt | tts
	Provider     string
	Model        string
	GenerationID string
	Chars        int
	InputUnits   int
	OutputUnits  int
	CostUSD      *float64
}

// NewMessage describes a message to store. ParentID is the message it replied
// to ("" for none); Format is "voice" or "text" ("" if not applicable).
type NewMessage struct {
	SessionID, Role, Text, AudioKey, ParentID, Format string
}

// ModelPrice is a model's per-token price (USD) and when it was last confirmed.
type ModelPrice struct {
	Prompt, Completion, Audio, CacheRead float64
	FetchedOn                            int64
}

// API response and request shapes. The json tags fix the field names clients
// see (snake_case) and the structs avoid the SQL null wrappers the database
// rows carry, so the HTTP contract stays stable when the schema changes.

type SessionView struct {
	ID        string        `json:"id"`
	Kind      string        `json:"kind"`
	URL       string        `json:"url,omitempty"`
	CreatedOn time.Time     `json:"created_on"`
	Messages  []MessageView `json:"messages"`
	Cost      CostView      `json:"cost"`
}

type MessageView struct {
	ID        string    `json:"id"`
	ParentID  string    `json:"parent_id,omitempty"`
	Role      string    `json:"role"`
	Format    string    `json:"format,omitempty"` // voice | text
	Text      string    `json:"text,omitempty"`
	AudioURL  string    `json:"audio_url,omitempty"`
	CreatedOn time.Time `json:"created_on"`
}

type CostView struct {
	TotalUSD     float64      `json:"total_usd"`
	Calls        int64        `json:"calls"`
	UnknownCalls int64        `json:"unknown_calls"`
	Ledger       []LedgerView `json:"ledger,omitempty"`
}

type LedgerView struct {
	Role         string    `json:"role"`
	Provider     string    `json:"provider"`
	Model        string    `json:"model"`
	GenerationID string    `json:"generation_id,omitempty"`
	Chars        int64     `json:"chars"`
	InputUnits   *int64    `json:"input_units"`
	OutputUnits  *int64    `json:"output_units"`
	CostUSD      *float64  `json:"cost_usd"` // null = not priced yet
	CreatedOn    time.Time `json:"created_on"`
}

// ThreadRequest is the body of POST /v1/threads.
type ThreadRequest struct {
	Adapter   string `json:"adapter"`
	ThreadRef string `json:"thread_ref"`
	MessageID string `json:"message_id"`
}

type ErrorBody struct {
	Error struct {
		Message string `json:"message"`
		Ref     string `json:"ref"`
	} `json:"error"`
}
